import { useEffect, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { CheckCircle2, Eye, EyeOff, KeyRound } from 'lucide-react'
import { api } from '@/lib/api'
import type { ToolItem } from '@/lib/api'
import { Modal, Button } from './ui'

interface EnvDialogProps {
  tool: ToolItem | null
  open: boolean
  onClose: () => void
}

/**
 * 环境变量配置弹窗：根据 tool.env_config_keys 动态渲染密码输入框。
 * 打开时拉取脱敏后的当前配置状态，保存时提交 PATCH /tools/{key}/env。
 */
export function EnvDialog({ tool, open, onClose }: EnvDialogProps) {
  const queryClient = useQueryClient()
  const [values, setValues] = useState<Record<string, string>>({})
  const [reveal, setReveal] = useState<Record<string, boolean>>({})

  const envKey = tool?.key ?? ''
  const { data: envInfo } = useQuery({
    queryKey: ['tool-env', envKey],
    queryFn: () => api.getToolEnv(envKey),
    enabled: open && !!envKey,
  })

  // 每次打开重置表单
  useEffect(() => {
    if (open) {
      setValues({})
      setReveal({})
    }
  }, [open, envKey])

  const declaredKeys = envInfo?.env_config_keys ?? tool?.env_config_keys ?? []
  const configured = envInfo?.env_configured ?? tool?.env_configured ?? {}
  const masked = envInfo?.env_masked ?? {}

  const saveMutation = useMutation({
    mutationFn: (vars: Record<string, string>) => api.patchToolEnv(envKey, vars),
    onSuccess: (res) => {
      if (res && res.success === false) {
        toast.error(res.error || '保存失败')
        return
      }
      toast.success('环境变量已保存')
      queryClient.invalidateQueries({ queryKey: ['tool-env', envKey] })
      queryClient.invalidateQueries({ queryKey: ['tools'] })
      onClose()
    },
    onError: (e: Error) => toast.error(e.message),
  })

  const handleSave = () => {
    // 仅提交有实际输入的字段
    const payload: Record<string, string> = {}
    for (const k of declaredKeys) {
      const v = values[k]
      if (v && v.trim()) payload[k] = v.trim()
    }
    if (Object.keys(payload).length === 0) {
      toast.error('请至少填写一个环境变量')
      return
    }
    saveMutation.mutate(payload)
  }

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={
        <span className="flex items-center gap-2">
          <KeyRound className="h-4 w-4 text-primary" />
          配置 {tool?.name ?? ''} 环境变量
        </span>
      }
      footer={
        <>
          <Button variant="ghost" onClick={onClose} disabled={saveMutation.isPending}>
            取消
          </Button>
          <Button variant="primary" onClick={handleSave} loading={saveMutation.isPending}>
            保存
          </Button>
        </>
      }
    >
      {declaredKeys.length === 0 ? (
        <p className="text-sm text-muted-foreground">该工具无需配置环境变量。</p>
      ) : (
        <div className="space-y-4">
          {declaredKeys.map((key) => {
            const isConfigured = !!configured[key]
            const shown = reveal[key]
            return (
              <div key={key} className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-medium font-mono">{key}</label>
                  {isConfigured && (
                    <span className="inline-flex items-center gap-1 text-xs text-green-600 dark:text-green-400">
                      <CheckCircle2 className="h-3.5 w-3.5" />
                      已配置{masked[key] ? ` (${masked[key]})` : ''}
                    </span>
                  )}
                </div>
                <div className="relative">
                  <input
                    type={shown ? 'text' : 'password'}
                    value={values[key] ?? ''}
                    onChange={(e) => setValues((prev) => ({ ...prev, [key]: e.target.value }))}
                    placeholder={isConfigured ? '留空则保持不变' : '输入值'}
                    autoComplete="off"
                    className="w-full rounded-lg border bg-background px-3 py-2 pr-10 text-sm font-mono placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/30"
                  />
                  <button
                    type="button"
                    onClick={() => setReveal((prev) => ({ ...prev, [key]: !prev[key] }))}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                    aria-label={shown ? '隐藏' : '显示'}
                  >
                    {shown ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      )}
    </Modal>
  )
}
